// Bundles the example maps (examples/*.mm) into js/examples.js, so the page works opened
// straight from disk (a page on file:// cannot fetch files). Run: node tools/bundle-examples.js
const fs = require("fs"), path = require("path");
const root = path.join(__dirname, "..");
const list = [
  ["stress-test", "Stress test: 60 nodes, every kind of node and link"],
  ["hub", "One hub, 14 branches"],
  ["forest", "Five small trees"],
  ["typical", "The app's typical demo"],
  ["tiny", "The app's tiny demo"],
  ["large", "The app's large demo: 316 nodes, 515 links"],
];
const examples = list.map(([file, title]) => ({ id: file, title, text: fs.readFileSync(path.join(root, "examples", file + ".mm"), "utf8") }));
const out = "// Generated by tools/bundle-examples.js from examples/*.mm; edit those and run it again.\n" +
  "(function (MM) {\n  MM.examples = " + JSON.stringify(examples, null, 1) + ";\n})(typeof window !== \"undefined\" ? (window.MM = window.MM || {}) : (globalThis.MM = globalThis.MM || {}));\n";
fs.writeFileSync(path.join(root, "js", "examples.js"), out);
console.log(`wrote js/examples.js: ${examples.length} maps, ${out.length} bytes`);
